27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public String getMembershipNumber() {
143	        return this.membershipNumber;
144	    }
145	
146	    public void setMembershipNumber(String membershipNumber) {
147	        this.membershipNumber = membershipNumber;
148	    }
149	
150	    public Boolean getBulkSignupWarning() {
151	        return this.bulkSignupWarning;
152	    }
153	
154	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
155	        this.bulkSignupWarning = bulkSignupWarning;
156	    }
157	
158	    public Integer getHouseholdSize() {
159	        return this.householdSize;
160	    }
161	
162	    public void setHouseholdSize(Integer householdSize) {
163	        this.householdSize = householdSize;
164	    }
165	
166	    /**
167	     * The owner's membership tier, derived at read time from stored fields: {@code 'GOLD'} when the
168	     * owner's {@link #getHouseholdSize() household} has 3 or more members (owners sharing the same
169	     * {@link #getHouseholdId() householdId}) as of this owner's creation; otherwise {@code 'SILVER'}
170	     * when {@link #getNamesakeCount() namesakeCount} is 0 and an email is present, otherwise
171	     * {@code 'BRONZE'}.
172	     */
173	    @Transient
174	    public String getMembershipTier() {
175	        if (this.householdSize != null && this.householdSize >= 3) {
176	            return "GOLD";
177	        }
178	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
179	        boolean hasEmail = this.email != null && !this.email.isBlank();
180	        return unique && hasEmail ? "SILVER" : "BRONZE";
181	    }
182	
183	    /**
184	     * The owner's region, derived at read time from the {@link #getCity() city} using a fixed
185	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}).
186	     * Any city not in the table yields {@code 'UNKNOWN'}.
187	     */
188	    @Transient
189	    public String getLocality() {
190	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
191	    }
192	
193	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
194	    private static final Map<String, String> CITY_REGION =
195	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
196	
197	    protected Set<Pet> getPetsInternal() {
198	        if (this.pets == null) {
199	            this.pets = new HashSet<>();
200	        }
201	        return this.pets;
202	    }
203	
204	    protected void setPetsInternal(Set<Pet> pets) {
205	        this.pets = pets;
206	    }
207	
208	    public List<Pet> getPets() {
209	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
210	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
211	        return Collections.unmodifiableList(sortedPets);
212	    }
213	
214	    public void setPets(List<Pet> pets) {
215	        this.pets = new HashSet<>(pets);
216	    }
217	
218	    public void addPet(Pet pet) {
219	        getPetsInternal().add(pet);
220	        pet.setOwner(this);
221	    }
222	
223	    /**
224	     * Return the Pet with the given name, or null if none found for this Owner.
225	     *
226	     * @param name to test
227	     * @return true if pet name is already in use
228	     */
229	    public Pet getPet(String name) {
230	        return getPet(name, false);
231	    }
232	
233	    /**
234	     * Return the Pet with the given name, or null if none found for this Owner.
235	     *
236	     * @param name to test
237	     * @return true if pet name is already in use
238	     */
239	    public Pet getPet(String name, boolean ignoreNew) {
240	        name = name.toLowerCase();
241	        for (Pet pet : getPetsInternal()) {
242	            if (!ignoreNew || !pet.isNew()) {
243	                String compName = pet.getName();
244	                compName = compName.toLowerCase();
245	                if (compName.equals(name)) {
246	                    return pet;
247	                }
248	            }
249	        }
250	        return null;
251	    }
252	
253	    public Pet getPet(Integer petId) {
254	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
255	    }
256	
257	    @Override
258	    public String toString() {
259	        return new ToStringCreator(this)
260	
261	            .append("id", this.getId())
262	            .append("new", this.isNew())
263	            .append("lastName", this.getLastName())
264	            .append("firstName", this.getFirstName())
265	            .append("address", this.address)
266	            .append("city", this.city)
267	            .append("telephone", this.telephone)
268	            .toString();
269	    }
270	}
