1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs in the create-owner pipeline after {@link AssignHousehold} (which stamps the shared
9	 * {@code householdId}) and before {@link SaveOwner}. Records how many owners share this owner's
10	 * household as of this create, so {@link Owner#getMembershipTier()} can award {@code 'GOLD'} when the
11	 * household reaches 3 or more members.
12	 *
13	 * <p>The owner being created is not yet persisted, so its own membership is counted with the seed
14	 * {@code 1} and every already-stored owner carrying the same non-null {@code householdId} adds one.
15	 * An owner with no household ({@code householdId == null}) is a household of one and never groups with
16	 * other household-less owners.
17	 */
18	public class AssignHouseholdSize {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        if (householdId == null) {
23	            owner.setHouseholdSize(1); // unique household — just this owner
24	            return;
25	        }
26	        int members = 1; // this owner, not yet saved
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (householdId.equals(existing.getHouseholdId())) {
29	                members++;
30	            }
31	        }
32	        owner.setHouseholdSize(members);
33	    }
34	}
